globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-25 23:01:17 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"中国の諜報機関が高性能AIチップの密輸を支援する秘密工作を少なくとも2年前から展開していたことが明らかに","url":"https://gigazine.net/news/20261125-china-spy-nvidia-chips/","source":"Hatena","published_at":"2026-11-25 18:49","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"中国諜報機関がAIチップ密輸を支援する秘密工作を展開","summary":"中国の情報機関である国家安全部（MSS）が、アメリカの輸出規制に対抗するため、高性能AIチップの調達や密輸を支援する専門チームを少なくとも2年前から設置していたことが明らかになった。先端技術の自給自足を国家課題とする中国は、国外データセンター経由の利用など、規制の抜け穴を突く工作を強化している。\n\nこれに対しアメリカ政府は、国外データセンター経由の計算能力利用を制限する新たな規制を導入するなど、AI開発競争を巡る攻防が激化している。技術の確保が国家安全保障に直結する現状を浮き彫りにするニュースである。","importance":9},{"title":"DBSC 入門: Cookie を盗まれても、攻撃者は使い続けられない仕組み","url":"https://zenn.dev/mittysan/articles/dbsc-device-bound-session-credentials","source":"Zenn","published_at":"2026-11-25 17:01","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cookie盗難を防ぐDBSCの仕組みと重要性","summary":"DBSC（Device Bound Session Credentials）は、ログイン後のCookieを特定のPCに紐付け、盗難されたCookieの悪用を数分で無効化する新しいセキュリティ技術である。PC内の秘密鍵で署名を行うことで、Cookieの再取得をブラウザが自動で行う仕組み。\n\nインフォスティーラーによるCookie盗難が多発する中、パスワードや多要素認証を突破された後のセッションハイジャックを防ぐ有効な手段となる。現在はChromeで対応が進んでおり、Webアプリのセキュリティを根本から強化する技術として期待される。","importance":9},{"title":"RustでFiberを用いたJob Systemを実装したらReleaseビルドでバグが発生した","url":"https://zenn.dev/otinpan/articles/082f6178eb1472","source":"Zenn","published_at":"2026-11-25 19:24","genre":"web","genre_label":"Web開発・言語","headline":"Rust製ゲームエンジンのFiber実装でReleaseビルド時にバグ発生","summary":"RustとVulkanを用いた自作ゲームエンジンにおいて、WindowsのFiber APIを用いたJob Systemを実装したところ、Releaseビルドでpanicや借用エラーが発生した。原因は、Fiberのスレッド間移動とコンパイラによるTLS（Thread Local Storage）アクセスの最適化の競合にあると推測される。\n\nJob Fiberは特定のOSスレッドに固定されず、負荷分散のためにスレッド間を移動する設計だが、TLSに依存したExecutorへのアクセスが最適化によって正しく機能しなくなったことが示唆されている。並列処理における低レイヤーな最適化の難しさを浮き彫りにする事例である。","importance":7},{"title":"地上波テレビの全番組を「ネットで同時・見逃し配信」、総務省が提案　2040年までに","url":"https://japan.cnet.com/article/35255356/","source":"Hatena","published_at":"2026-11-25 09:43","genre":"other","genre_label":"総合・その他IT","headline":"総務省、2040年までに地上波テレビ全番組のネット同時・見逃し配信を提案","summary":"総務省の放送政策委員会は、2040年までに地上波テレビ番組を原則すべてネット配信する案を提示しました。中継局の設備更新時期を見据え、ネット配信による視聴手段確保を前提とした小規模中継局の廃止も視野に入れています。\n\n民放連は権利処理の負担や経営課題を指摘しており、実現には法整備や役割分担の議論が不可欠です。放送インフラの維持とネット配信の融合が、今後のテレビ視聴の大きな転換点となります。","importance":7},{"title":"タイムズカー免許画像漏えいの見舞金、「現金かカーシェアeチケット3000円分」　12月1日から案内","url":"https://www.itmedia.co.jp/news/article/2611/25/2000003443/","source":"Hatena","published_at":"2026-11-25 15:59","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"タイムズカー免許画像漏えい、見舞金3000円の案内を開始","summary":"タイムズカーへの不正アクセスによる本人確認書類の画像漏えい問題で、パーク24は対象会員に対し3000円の現金またはeチケットによる見舞金の提供を開始する。対象は約146万件にのぼり、特別損失として55億円を計上する見込み。\n\n見舞金の額が「低すぎる」として集団訴訟の動きもあり、企業の情報管理責任が厳しく問われている。退会後も長期間データを保管していたことへの批判もあり、個人情報の取り扱いに関するガバナンスの重要性が改めて浮き彫りとなった。","importance":8},{"title":"AIで学習アプリを作って2週間で宅建に合格した話【テキスト不要】｜Shikimi","url":"https://note.com/shikimi_crypto/n/n35d0bb54e6fb","source":"Hatena","published_at":"2026-11-25 18:23","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AI活用と自作アプリで宅建試験に2週間で合格した戦略","summary":"不動産業界未経験のコンサルタントが、試験2週間前からAIを活用した学習アプリを自作し、市販テキストなしで宅建試験に合格した事例。まずは過去問で現在地を把握し、学習・演習・フィードバック機能を備えたアプリを開発して効率を最大化した。\n\n「宅建業法」を最優先し、民法をロジックで理解する戦略をとることで、短期間での学習を成功させた。AIを単なるツールとしてだけでなく、学習プロセスそのものを最適化するエージェントとして活用した点が特徴的であり、資格学習におけるAI活用の可能性を示している。","importance":6},{"title":"結局「オントロジー」って何なのさ 〜概念と良さを4つのレイヤーで整理する〜","url":"https://zenn.dev/algomatic/articles/ece749a7e3cb24","source":"Zenn","published_at":"2026-11-25 18:23","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代に注目される「オントロジー」の概念と良さを整理","summary":"AIが企業のデータを文脈として理解するために不可欠な「オントロジー」について、その概念を4つのレイヤーで整理した解説。オントロジーは、クラス・関係・インスタンス・プロパティを定義し、データに意味的な文脈を付与する技術である。\n\n狭義の設計図から、実データを含むナレッジグラフ、そしてPalantirが提唱する操作可能なオペレーション層まで、用語の指す範囲が広いことが理解を難しくしている。AIとオントロジーを組み合わせることで、機械的なデータを業務のコンテキストとして活用できる点が最大の強みである。","importance":8},{"title":"OSC 2026 Nagaokaに行ってきました！！","url":"https://zenn.dev/tayu99_make/articles/1448f04c300c1f","source":"Zenn","published_at":"2026-11-25 15:01","genre":"other","genre_label":"総合・その他IT","headline":"長岡で開催されたOSC 2026 Nagaokaの参加レポートと技術的知見","summary":"長岡技術科学大学の学生が、20周年を迎えた「オープンソースカンファレンス 2026 Nagaoka」に参加した体験記。雪国特有の課題である消雪パイプの渇水監視IoTシステムや、MySQLの最新リリース体制（LTSとInnovationの分離）など、現場の技術者による興味深い知見が共有されています。\n\nイベントでは、OSSを活用してコストを抑えた監視システムの事例や、MySQLのコミュニティ運営に関する裏話などが語られました。学生の視点から、地域課題と最新技術がどう結びついているかを学べる貴重な機会となっており、オープンソース文化の広がりと重要性が再確認できる内容です。","importance":4},{"title":"AWS セキュリティ成熟度モデル v3 と PCI DSS 版・AI 版の変更点と評価ツールを確認する","url":"https://zenn.dev/cscloud_blog/articles/new-aws-security-maturity-model","source":"Zenn","published_at":"2026-11-25 18:41","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWSセキュリティ成熟度モデルv3の変更点と活用法","summary":"AWSセキュリティ成熟度モデルがv3にアップデートされ、Cloud版に加え、PCI DSS版とAI版が追加された。v3では評価ツールがWebアプリ化され、AWS CAFやWell-Architected、NIST CSFとの対応表示が可能になるなど、利便性が向上している。\n\n特に生成AI関連のコントロール（LLMjacking対策やAIコーディングアシスタントのレビュー等）が追加され、現代の脅威に対応した構成となっている。監査チェックリストではなく、セキュリティ運用のロードマップとして活用することで、組織のセキュリティレベルを段階的に向上させることが可能である。","importance":8},{"title":"マーダーミステリーのシナリオを形式手法で検証しようとしたら、バグと曖昧さが見つかった","url":"https://zenn.dev/henteko/articles/ed8d1458246d7a","source":"Hatena","published_at":"2026-11-25 17:07","genre":"web","genre_label":"Web開発・言語","headline":"マーダーミステリーのシナリオ検証に形式手法を導入","summary":"マーダーミステリーのシナリオにおける矛盾を検出するため、Lean 4を用いた形式手法による検証CLIを開発した。シナリオを仕様としてモデル化することで、到達不能なエンディングやアイテムの矛盾などを機械的に判定可能にした。\n\n検証プロセスを通じて、シナリオ記述の曖昧さや論理的な穴が発見されるなど、形式手法が創作物の品質向上に寄与することが示された。AIによるシナリオ生成の自動判定や、複雑なゲームデザインの検証手法として応用が期待される。","importance":6},{"title":"「半導体氷河期」を招く3つの衝撃――トランプ敗北、NVIDIAの経営混乱、メモリ各社の巨額投資","url":"https://eetimes.itmedia.co.jp/ee/articles/2611/25/news044.html","source":"Hatena","published_at":"2026-11-25 12:01","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"半導体市場のメモリバブルと2028年「半導体氷河期」の予測","summary":"AIデータセンターへの巨額投資によるメモリ不足と価格高騰が、2028年に深刻な供給過剰と不況を招く可能性を指摘。米国の政治情勢、NVIDIAの経営混乱、メモリ各社の設備投資という3つの衝撃が連鎖するリスクを分析しています。\n\nAI需要が民生市場の生産資源を奪う現状を「ブラックホール」と表現し、需要の先食いと供給能力の拡大が重なった際の暴落リスクを警告。半導体業界の好況が永続的ではないことを示唆し、中長期的な市場予測の重要性を説いています。","importance":8},{"title":"月1万円の専用サーバー代を浮かせたくて、UE5でTrueP2Pというプラグインを作った【設計と仕様編】","url":"https://zenn.dev/expevodev/articles/ue5-truep2p-client-to-client","source":"Zenn","published_at":"2026-11-25 09:52","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"UE5でサーバー代を節約するフルメッシュP2Pプラグイン「TrueP2P」開発","summary":"UE5での対戦ゲーム開発において、高額な専用サーバー費用を削減するため、サーバーを介さないフルメッシュP2P通信を実現するプラグイン「TrueP2P」が開発されました。\n\nUE標準のListen Serverと異なり、ホスト離脱による試合終了を防ぎ、公平な対戦環境を提供します。Online Beaconを活用してワールドのNet Modeを維持しつつ、アクターのオーナー管理を工夫することで、既存のReplicated等の仕組みをそのまま利用できる設計が特徴です。","importance":7},{"title":"AIでドーピングしたコンサルの実力は　使わない人材との能力差、BCG約500人で検証　Nature系列誌","url":"https://www.itmedia.co.jp/news/article/2611/25/2000003421/","source":"Hatena","published_at":"2026-11-25 12:07","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"生成AIによるコンサルタントのスキルアップ効果と限界の検証","summary":"BCGのコンサルタント約500人を対象に、生成AIが専門外の業務に与える影響を調査した研究論文の解説。AIは専門外の課題において作業効率と品質を大幅に向上させる「パワードスーツ」として機能することが判明しました。\n\nしかし、AIの使用を止めるとそのスキルアップ効果は消失し、知識として定着していないことも明らかに。AIへの過度な依存が技術力の低下を招く懸念と、AIの能力を過大評価する心理的バイアスについても警鐘を鳴らしており、AI活用における教育的示唆に富む内容です。","importance":9},{"title":"EXT4に4万行のAI生成コード、rcサイクル終盤の投入にトーバルズ氏が警告","url":"https://joho-todai.com/ext4-ai-generated-code-linus-warning/","source":"Hatena","published_at":"2026-11-25 14:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Linuxカーネルへの大量AI生成コード投入に対するトーバルズ氏の警告","summary":"EXT4ファイルシステムのメンテナがLinux 7.4-rc5向けに4万行超のプルリクエストを提出し、リーナス・トーバルズ氏が「次は無視する」と警告。追加コードの大半はAI生成のテストコードであり、リリース候補段階での大規模な変更という開発プロセスの規律違反が問題視されました。\n\n一方で、同プルリクエストに含まれていたSamsungによる80行のパッチは、並列ファイル作成を最大2.7倍高速化する高い価値を持つものでした。コードの量と質が比例しない現状と、AI生成コードを扱う際の開発サイクルにおける適切なタイミングと検証の重要性が浮き彫りになっています。","importance":9},{"title":"15分かかっていたCIを数分に — 内訳を測り、ランナーは同じコミットで並べて比べ、テストを3シャードに分けた","url":"https://zenn.dev/rehabforjapan/articles/ci-runner-compare-test-shards-202611","source":"Zenn","published_at":"2026-11-25 13:41","genre":"web","genre_label":"Web開発・言語","headline":"CIの実行時間を16分から数分に短縮した最適化の取り組み","summary":"Spring BootプロジェクトのGitHub ActionsによるCIが16分かかっていた問題を、工程ごとの内訳分析とキャッシュ戦略の改善により大幅に短縮した事例。Claude Codeを活用してボトルネックを特定し、テストの並列化やキャッシュの有効活用を行いました。\n\n特に、setup-gradleの既定ブランチ以外でのキャッシュ保存問題への対処や、ランナーの性能比較を同じコミットで同時に流して行う手法が非常に実践的です。CIの待ち時間に悩む開発者にとって、具体的な改善プロセスが参考になります。","importance":7},{"title":"我々はもう少し、Googleに怒っていいと思う","url":"https://blog.tinect.jp/?p=91593","source":"Hatena","published_at":"2026-11-25 08:52","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Googleの「AIによる概要」はNAVERまとめと同じ盗用ではないか","summary":"かつて著作権侵害としてGoogleに排除された「NAVERまとめ」と、現在のGoogle「AIによる概要」の類似性を指摘する論考。AIがWeb情報を要約して表示することで、オリジナルのサイトへのトラフィックが失われる「ゼロクリック検索」がコンテンツ制作者の死活問題となっています。\n\nGoogleが自らの権力を乱用し、共存共栄の道を捨てている現状に対し、コンテンツメーカーはAI検索対策を講じる必要に迫られています。","importance":8},{"title":"窓の内側に貼って屋外を撮影する防犯カメラ　Ankerが9990円で発売","url":"https://japan.cnet.com/article/35255394/","source":"Hatena","published_at":"2026-11-25 17:33","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Ankerが窓の内側に貼る屋外撮影用防犯カメラを発売","summary":"アンカー・ジャパンは、窓ガラスの内側に貼り付けて屋外を撮影できる防犯カメラ「Anker Eufy Window Camera E10」を9,990円で発売した。工事不要で設置でき、電源は室内のコンセントから供給する。\n\nカメラ本体のAIが人やペット、車両を識別し、指定した対象のみを検知して通知する機能を備える。屋外配線や壁への穴あけができない賃貸住宅などにおいて、防犯カメラを導入したいというニーズに応える製品であり、手軽なセキュリティ対策として注目される。","importance":5},{"title":"「Claude」で作ったアプリをMac／Windowsにインストール可能に　全プランでβ提供","url":"https://www.itmedia.co.jp/news/article/2611/25/2000003431/","source":"Hatena","published_at":"2026-11-25 10:11","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claudeの「アーティファクト」がデスクトップアプリとしてインストール可能に","summary":"Anthropicは、Claudeで生成した成果物「アーティファクト」をMac/Windowsの専用デスクトップアプリとしてインストールできる「Install as app」機能を全プランでβ提供開始しました。\n\nインストールしたアプリは専用ウィンドウで動作し、通知やファイル操作などの権限付与も可能です。プログラミング知識がなくても、Claudeとの対話を通じて日常業務ツールを自作・共有できる点が特徴です。ただし、利用にはデスクトップアプリ版の最新環境が必要です。","importance":9},{"title":"高木浩光＠自宅の日記 - 「氏名は含まれておりません」では済まない——KARTE事件で漏れた行動の記録は誰の個人データか","url":"http://takagi-hiromitsu.jp/diary/20261124.html","source":"Hatena","published_at":"2026-11-25 09:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"KARTE事件で浮き彫りになった「氏名なし」個人データの漏えいリスク","summary":"KARTEの不正アクセス事件において、多くの企業が「氏名が含まれないため個人情報ではない」と公表している現状に対し、高木浩光氏が警鐘を鳴らしています。\n\n会員番号や行動記録であっても、企業側で特定の個人と照合可能であれば個人データに該当します。氏名の有無で個人情報の定義を狭める公表姿勢は誤りであり、漏えいしたデータが自社にとってどのような意味を持つかを正しく認識し、報告する必要があると指摘しています。","importance":9},{"title":"Rubyを安心して使い続けるために","url":"https://www.ruby.or.jp/ja/news/20261125","source":"Hatena","published_at":"2026-11-25 12:12","genre":"web","genre_label":"Web開発・言語","headline":"AI時代の脆弱性リスクとRubyの安全な運用に向けた提言","summary":"AIの普及により脆弱性の発見から悪用までの時間が短縮される中、Rubyアソシエーション理事長のまつもとゆきひろ氏が、Rubyを安全に使い続けるための運用指針を提示。\n\nサポートされているバージョンの利用、フレームワークやgemの迅速な更新、そして経営層を含めたセキュリティ対策へのリソース確保を強く求めています。攻撃の高速化が進む現代において、セキュリティ修正の適用は開発現場だけの課題ではなく、事業継続のための必須事項であると強調しています。","importance":7},{"title":"アウトプットの「質」ってじゃあなんなんだよ","url":"https://zenn.dev/watany/articles/1efe3adea67dd5","source":"Zenn","published_at":"2026-11-25 20:31","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代に求められる「アウトプットの質」とは何か","summary":"AIが情報を要約・生成できる時代において、人間が発信するアウトプットには「AIには代替できない価値」が求められている。公式ドキュメントからの逸脱や独自の体験談、歴史的背景の整理、そして何より書き手の「我」やオピニオンが重要である。\n\nまた、情報の出し順の設計や、媒体に合わせた分量の精査、そして「読み上げ」による推敲など、受け手への配慮が不可欠である。AIに頼るべき作業と、人間が責任を持って構築すべきコンテンツを明確に分けることが、これからの発信者に求められる姿勢である。","importance":6},{"title":"RTX 5090を買ったからGPUサーバーを構築していくぞ その1（Ubuntu Server・vLLM編）","url":"https://zenn.dev/luxiar/articles/7eff2306ffb0c6","source":"Zenn","published_at":"2026-11-25 14:20","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"RTX 5090搭載GPUサーバーの構築とvLLMによるローカルLLM実行","summary":"RTX 5090を購入したエンジニアによる、Ubuntu Serverを用いたローカルLLM実行環境の構築記録。NVIDIAドライバーのセットアップから、推論エンジンvLLMの導入、Python仮想環境の構築までを詳細に解説しています。\n\n実際にQwen2.5-1.5Bモデルを動かし、OpenAI互換API経由で応答を得るまでの手順を網羅。ハードウェアの性能を最大限に引き出すための設定や、Cコンパイラ等の依存関係解決など、ローカルLLM環境を自作したいユーザーにとって実践的な参考資料となります。","importance":6},{"title":"5.9GBでエージェント性能アップ！「Ternary Bonsai 2.5 27B」登場","url":"https://pc.watch.impress.co.jp/docs/news/2159034.html","source":"Hatena","published_at":"2026-11-25 13:56","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"5.9GBの軽量モデル「Ternary Bonsai 2.5 27B」の性能と特徴","summary":"PrismMLが公開した「Ternary Bonsai 2.5 27B」は、270億パラメータのモデルを3値量子化により5.9GBに圧縮しつつ、コーディングエージェントとしての性能を大幅に向上させたモデルです。\n\nSWE-bench Verifiedなどのベンチマークでフル精度版に迫るスコアを記録し、エージェントワークフローにおけるツール利用や多段階タスクの実行能力が強化されています。軽量かつ高性能なモデルとして、ローカル環境でのエージェント開発における有力な選択肢となります。","importance":8},{"title":"M＆A仲介会社に不正アクセス 最大数千社分の顧客情報漏えいか | NHKニュース","url":"https://news.web.nhk/newsweb/na/nd-20261125de81289","source":"Hatena","published_at":"2026-11-25 18:13","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"M＆A仲介会社への不正アクセスで数千社分の情報漏えいか","summary":"MJS M＆Aパートナーズが不正アクセスを受け、最大数千社分の顧客情報が外部に漏えいした可能性があると発表した。中小企業の事業承継や合併を扱う企業であり、機密性の高い情報が含まれていることが懸念される。\n\n企業を標的とした不正アクセスは依然として深刻な脅威であり、特にM&Aのような高価値な情報を扱う企業では、より強固なセキュリティ対策とインシデント対応体制が求められる。被害の全容解明と再発防止策が急がれる。","importance":7},{"title":"moejsはSobekの半分以下、正規表現を使う処理ではgo-quickjsが逆転： pure Go製JSエンジン3種を同じプラグインで比較","url":"https://zenn.dev/nonejp/articles/3bbffb1db9c4ce","source":"Zenn","published_at":"2026-11-25 10:00","genre":"web","genre_label":"Web開発・言語","headline":"Go製JSエンジン3種比較：moejsは軽量、正規表現処理ではgo-quickjsが優位","summary":"Goサーバーに組み込み可能なpure Go製JSエンジン「Sobek」「moejs」「go-quickjs」の性能比較が行われました。moejsはSobekと比較してメモリ効率と呼び出し速度で優位性を示しています。\n\n一方で、正規表現を多用する処理ではgo-quickjsが最も高速であるという結果が得られました。各エンジンは設計思想が異なるため、大量のランタイムを動かす用途にはmoejs、特定の計算性能を求める場合はgo-quickjsなど、用途に応じた選択が重要です。","importance":6},{"title":"体験ドリブンのすすめ ― AIで作れる時代に、何で差がつくか","url":"https://zenn.dev/mediaforce/articles/2fef9933aae9e7","source":"Zenn","published_at":"2026-11-25 11:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代に求められる「体験ドリブン」な開発アプローチ","summary":"AIによって開発スピードが向上した今、成果物の中身だけでなく、ユーザーがシステムとどう関わるかという「体験」で差をつける重要性を説く記事。システム移行時のヒアリングを例に、Excelでの確認作業を「触れるページ」に変えることでユーザーの負担を軽減した事例を紹介しています。\n\nAIを「速くする道具」ではなく「やらなかったことをやれるようにする装置」と定義し、エンジニアが顧客体験の設計に時間を割くべきだと主張。技術力だけでなく、顧客の心理や業務フローを深く理解する姿勢が、これからの開発者に求められる価値であると示唆しています。","importance":6},{"title":"DPIの違うモニタ間でウィンドウが飛ぶ：winitのWM_DPICHANGEDバグをHWNDサブクラス化で直した","url":"https://zenn.dev/kuwashima/articles/winit-dpi-multimonitor-drag","source":"Zenn","published_at":"2026-11-25 12:52","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"マルチモニタ環境でのウィンドウ位置ずれをHWNDサブクラス化で修正","summary":"Rust+egui製のアプリで、DPIの異なるマルチモニタ環境においてウィンドウをドラッグした際に位置が飛ぶ問題を、WindowsのWM_DPICHANGEDハンドラの修正により解決した技術記録。\n\nwinitの再配置ロジックがモニタのオフセットを考慮していないことが原因であり、HWNDをサブクラス化してドラッグ中の位置を強制的に矯正するワークアラウンドを採用。OSレベルのイベントループとフレームベースのGUI更新の乖離を埋めるための高度なデバッグ事例です。","importance":5},{"title":"Qwen3.8 27Bを5.9GBまで省メモリ化しつつエージェント性能を維持したAIモデル「Ternary Bonsai 2.5 27B」が公開される","url":"https://gigazine.net/news/20261125-ternary-bonsai-2-5-27b/","source":"Hatena","published_at":"2026-11-25 10:39","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Qwen3.8 27Bを5.9GBまで軽量化した「Ternary Bonsai 2.5 27B」公開","summary":"PrismML社が、Qwen3.8 27Bをベースにウェイトを3値（-1, 0, 1）で扱うことで劇的な省メモリ化を実現した「Ternary Bonsai 2.5 27B」を公開しました。前バージョンからエージェント性能が向上し、オフライン環境での複雑なタスク実行も可能です。\n\n本モデルはApache License 2.0で公開されており、Appleシリコン向けMLX版も提供されています。軽量かつ高性能なローカルAIとして、エージェント開発やプライベートな知識作業での活用が期待されます。","importance":8},{"title":"「Todoist」に不正アクセス、ユーザーの約6％でメールアドレスとパスワードハッシュが流出／廃止予定の「Microsoft To Do」の代替として期待されるタスク管理サービスだが……","url":"https://forest.watch.impress.co.jp/docs/news/2159145.html","source":"Hatena","published_at":"2026-11-25 17:21","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"タスク管理サービス「Todoist」で不正アクセスによる情報流出","summary":"タスク管理サービス「Todoist」の本番システムが不正アクセスを受け、全ユーザーの約6％でメールアドレスやパスワードハッシュが流出した。攻撃者は盗まれた認証情報を悪用し、自動化ワークフローを改変してクラウドインフラへ侵入した。\n\n同社はパスワードの無効化やAPIトークンの失効などの措置を実施済み。SHA1ベースの古いハッシュが残っていたことが課題として指摘されている。ユーザーは通知を確認し、パスワード変更や連携アプリの再接続などの対応が求められる。","importance":7},{"title":"Ghostty で SSH 先に入ると、Backspace で文字が消えずに増えていく","url":"https://zenn.dev/kazuma_horiike/articles/c9b7b64d0e62f4","source":"Zenn","published_at":"2026-11-25 14:42","genre":"web","genre_label":"Web開発・言語","headline":"GhosttyでSSH先での表示崩れを防ぐterminfo設定の解説","summary":"新しいターミナル「Ghostty」を使用してSSH接続した際、Backspaceキーなどで表示が崩れる現象の原因と解決策を解説。これは接続先のOSにGhosttyのterminfo（制御文字の辞書）が存在しないために発生する問題です。\n\n解決策として、手元のterminfoを接続先にコピーする方法や、GhosttyのSSH設定を活用する手法が紹介されています。新しいターミナルへ移行する際に遭遇しやすいトラブルであり、同様の仕組みを持つkittyなどのターミナル利用者にとっても役立つ技術的知見です。","importance":5},{"title":"34年目の秀丸エディタと、AIの距離感　「正直皆どんな目的で使ってるかよく分かりません」 - レバテックLAB","url":"https://levtech.jp/media/detail_973/","source":"Hatena","published_at":"2026-11-25 09:58","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"34年続く「秀丸エディタ」開発陣が語る、AIとの距離感と活用法","summary":"長年愛されるテキストエディタ「秀丸」シリーズの開発元であるサイトー企画へのインタビュー記事。エディタ本体にはAI機能を組み込んでいないものの、社内開発ではClaude Codeを活用し、30年分のソースコード解析やバグ発見に役立てています。\n\n開発陣は、AIの回答にはまだ実行時の挙動との乖離があるとしつつも、コード解析の補助としては実用的であると評価しています。ユーザーからのAI要望が少ない現状を踏まえ、慎重かつ実利的な距離感を保っています。","importance":5},{"title":"ずっしり重い新型ウォークマン　歴代最高65万円なぜここまで高級化：朝日新聞","url":"https://www.asahi.com/articles/ASVCN2QXSVCNULFA01XM.html","source":"Hatena","published_at":"2026-11-25 08:35","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ソニー新型ウォークマンが65万円に高騰した理由と高級化の背景","summary":"ソニーが発売する新型ウォークマンの旗艦モデルが約65万5千円という歴代最高額になった背景を解説。材料費や人件費の高騰に加え、音質向上のための銅素材の多用や、デジタル・アナログ分離の電力供給設計など、細部へのこだわりが価格に反映されています。\n\nかつてアルミ製だったフレームを銅に変更し、重量を増やすことで低音の臨場感を高めるなど、音楽愛好家向けの高級オーディオ機器としての地位を確立しています。","importance":5},{"title":"Personal Agent Protocol (Poppy) が解く問題と仕組み","url":"https://zenn.dev/sierra_japan/articles/0b9ba590232345","source":"Zenn","published_at":"2026-11-25 08:30","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"パーソナルAIエージェントと企業をつなぐ「Poppy」プロトコルの仕組み","summary":"MetaとSierraが発表した「Personal Agent Protocol (Poppy)」は、ユーザーのエージェントと企業サイト間の安全な連携を実現するオープンプロトコルです。\n\nエージェントの不正利用を防ぎつつ、ユーザーが権限を細かく制御できる仕組みを提供します。企業はpoppy.jsonで公開するAPIやWeb経路を通じてエージェントを受け入れ、ユーザーは「閲覧のみ」「購入は承認が必要」といった段階的な権限付与が可能です。Shopifyなどが導入を進めています。","importance":8},{"title":"Claude Code のセキュリティ、2026年11月時点のベストプラクティス（サンドボックス・権限・MCP）","url":"https://zenn.dev/happy_elements/articles/27e14ff6754044","source":"Zenn","published_at":"2026-11-25 12:53","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Claude Codeのセキュリティを強化するベストプラクティス","summary":"Claude Code CLIを安全に利用するための、権限設定とOSレベルの隔離を組み合わせたセキュリティ対策の解説。Bashサンドボックスの活用や、ツール実行時の権限ルール設定など、2026年11月時点での推奨設定をまとめています。\n\nプロンプトインジェクション対策として、Claude Codeの設定とOSの隔離（Seatbeltやbubblewrap）の両面から制限をかける重要性を強調。認証情報や機密ファイルへのアクセスを制御しつつ、安全にAIエージェントを開発するためのチェックリストを提供しています。","importance":8},{"title":"Git for Windows の connect.exe で SSH の上りが遅い原因を追った話","url":"https://zenn.dev/akarineren/articles/13ee3a909672c7","source":"Zenn","published_at":"2026-11-24 23:29","genre":"web","genre_label":"Web開発・言語","headline":"プロキシ越しに SSH のポートフォワードで RDP を使っていたところ、画面の操作が妙に重いことに気づきました。","summary":"プロキシ越しに SSH のポートフォワードで RDP を使っていたところ、画面の操作が妙に重いことに気づきました。調べてみると、 上り（クライアント → サーバー）だけが約 0.5Mbps しか出ていません 。\n\n下りは普通に速いのに、です。原因は SSH の ProxyCommand に使っていた connect.exe （Git for Windows に同梱されているもの）でした。\n\nこの記事では、原因の特定から、MSYS2 と上流の gotoh/ssh-connect にそれぞれ PR を出してマージされるまでをまとめます。~/.ssh/config はよくある形です。\n\n（古い Git for Windows では mingw64/bin/connect.exe にあります） connect.exe は ssh と標準入出力（パイプ）でつながり、stdin から読んだデータをソケットへ、ソケットから読んだデータを stdout へ中継します。","importance":5},{"title":"なんとなくgrill-meしている人に伝えたい、作者本人から学んだSkillsの使い方","url":"https://zenn.dev/mediaforce/articles/27df1f22a00546","source":"Zenn","published_at":"2026-11-25 07:30","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"株式会社メディアフォースでエンジニアをしている池田です。","summary":"株式会社メディアフォースでエンジニアをしている池田です。自社プロダクトの開発を担当しています。\n\n弊社の開発チームは、設計や実装にClaude Codeを利用しています。周りのエンジニアに勧められたことをきっかけに、最近はMatt PocockのSkillsを利用しています。\n\nこのSkillsは2026年春頃から話題になっていたgrill-me（grilling） [1] を含んだスキル集です。仕様の曖昧さを排除しながら設計できる便利さを感じつつも、質問の多さに疲れたり、途中で仕事の進め方を見失ったりと、時折使いこなせていないと感じることも出てきました。\n\nそこで、公式ドキュメントや彼の発言、実際に開発している姿から学んだことを取り入れてみました。その結果、Skillsに振り回されることが減り、本来の便利さを活かせるようになりました。\n\nこの記事では、その学びを紹介します。","importance":5},{"title":"AIエージェントのMemory設計 ― 会話履歴・業務データ・長期Memoryの使い分け","url":"https://zenn.dev/taru_neko/articles/ai-agent-memory-architecture-2026","source":"Zenn","published_at":"2026-11-25 14:23","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントにおける短期・長期Memoryの設計と使い分け","summary":"AIエージェント開発において、会話履歴（短期）と業務データやユーザー設定（長期）のMemoryをどう設計・管理すべきかを解説。単に専用のDBを用意するのではなく、既存の業務システムやRAG技術との適切な使い分けが重要であると説いています。\n\nLangGraphのPersistence機能などを例に、会話の文脈維持と処理の進行状態保持の論理構成を整理。何を記憶し、いつ更新・削除するかという設計判断の指針を示しており、実用的なエージェント構築を目指すエンジニアにとって有益なガイドラインです。","importance":7},{"title":"C言語が危険なのではない。コンピュータが危険なのだ - keroxpのScrapbox","url":"https://scrapbox.io/keroxp/C%E8%A8%80%E8%AA%9E%E3%81%8C%E5%8D%B1%E9%99%BA%E3%81%AA%E3%81%AE%E3%81%A7%E3%81%AF%E3%81%AA%E3%81%84%E3%80%82%E3%82%B3%E3%83%B3%E3%83%94%E3%83%A5%E3%83%BC%E3%82%BF%E3%81%8C%E5%8D%B1%E9%99%BA%E3%81%AA%E3%81%AE%E3%81%A0","source":"Hatena","published_at":"2026-11-25 09:40","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"C言語の脆弱性問題の本質はメモリ管理とデータの「幅」の理解にある","summary":"C言語に起因するメモリ破壊バグが多発する現状に対し、プログラマがメモリの本質を理解すべきだと説く解説記事。メモリは0と1の連続した1次元構造であり、データには「幅（ビット）」という概念が不可欠であることを強調しています。\n\nデジタルデータには自己定義能力がないため、読み書きのルールはプログラマの責任に委ねられています。C言語が危険なのではなく、メモリの物理的構造とデータ表現の仕組みを深く理解しないまま扱うことがリスクの本質であると指摘しています。","importance":8},{"title":"歌った直後に30秒喋るだけ。カラオケの振り返りレポートを自動で作る仕組みを作った","url":"https://zenn.dev/semjin/articles/d6f543e4c75b07","source":"Zenn","published_at":"2026-11-25 02:23","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"歌って、歌い終わったら30秒ほど感想を喋る。","summary":"歌って、歌い終わったら30秒ほど感想を喋る。それだけで、 「自分の感覚（自覚）」と「ピッチの実測」を並べた振り返りレポートが出る仕組みを作りました。\n\nカラオケの練習では、以前から歌唱録音を分析して、安定感や音域といった「実測」を取っていました。足りなかったのは「自分がどう感じたか」の記録です。\n\n感覚はその場で消えてしまい、あとから実測と突き合わせることができませんでした。そこで、既存の音程解析を土台に口頭レビューを取り込み、 録音1本から「自覚 × 実測」のレポートが一連で出るようにしました。\n\n歌い終わったら、その場で30秒ほど口頭で振り返る （「サビは安定していた」「二番の頭でふらついた」「力んだ」など） 録音をスクリプトに渡すと、レポートが出る 出力されるレポートはこんな形です（自宅で歌った録音に実際にスクリプトを通した出力から。歌唱ブロックは計4つあり、代表で1つだけ載せます）。\n\nポイントは、 本人の自覚（口頭レビューの文字起こし）と実測（ピッチなどの数値）が、同じレポートに並ぶ ことです。","importance":5},{"title":"Corpus2Skillに近づけた「階層ナビゲーション型RAG」と、ベクトルDB版RAGを「どの段階で失敗したか」まで比べてみた","url":"https://zenn.dev/aiforall/articles/133752ce2d97ad","source":"Zenn","published_at":"2026-11-25 11:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"階層ナビゲーション型RAGとベクトルDB版RAGの性能比較分析","summary":"ベクトルDBを使わずにLLMが目次を辿る「階層ナビゲーション型RAG」と、従来のベクトルDB版RAGを比較検証。130文書・40問のテストにおいて、エージェント型が正答率でベクトルDB版を上回る結果となりました。\n\n特に複数の文書にまたがる質問での優位性が顕著であり、失敗段階を「文書到達」「根拠保持」「回答」の3段階に分けて分析。エージェント型はコストと時間がかかるものの、複雑な検索タスクにおいて高い精度を発揮することが示されており、RAGの設計手法に新たな視点を提供しています。","importance":7},{"title":"Yocto で脱 GPLv3 構成を作り、ビルドごとに OSS ライセンス一覧を自動生成する","url":"https://zenn.dev/remote_sw/articles/3777969dd3a4de","source":"Zenn","published_at":"2026-11-25 16:35","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"YoctoでGPLv3を排除しOSSライセンス一覧を自動生成する構成","summary":"組込みLinux製品において、GPLv3のインストール情報条項を回避するため、Yoctoを用いてrootfsからGPLv3パッケージを排除する構成を構築した。INCOMPATIBLE_LICENSEを活用し、GPLv2版への差し替えや不要なパッケージの削除を行うことで対応している。\n\nさらに、ビルドごとにlicense.manifestからOSSライセンス一覧を自動生成する仕組みを導入し、ライセンス遵守の管理を効率化した。製品出荷時の法的リスクを低減しつつ、管理コストを最小化する実践的なYocto運用手法である。","importance":7},{"title":"エンジニア20人の組織を、デザイナー1人と AI で支える仕組み","url":"https://zenn.dev/rimo/articles/c25919207b1cde","source":"Zenn","published_at":"2026-11-24 17:24","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"こんにちは。","summary":"こんにちは。Rimo 合同会社で 1人目デザイナーをやっているにしゃみー (@NishaMe1024) です。\n\nRimo にはエンジニアが約20人いて、正社員のデザイナーは入社した3年前から相変わらず私1人です。今年の2月頃、Claude が超絶進化したのを皮切りにプロトタイプを作らせる仕組みを自作し、8ヶ月近くデザイナー1人でもこの人数の開発を支えられる体制をつくってきたので、今回は仕組みや溜まった知見についてご紹介します。\n\n7月のデザインハーネスイベントで登壇したときの内容がベースですが、5分の登壇では話しきれなかった裏側の話もいれて内容をアップデートして書いていきます。✍️ AI 活用推進のきっかけ 言わずもがなですが、どうやってもUIデザインの手が足りませんでした。\n\n当初は Figma Make などの AI の力を借りつつ、Figma を中心としたデザイン環境で仕事をしていました。","importance":5},{"title":"Agentforce エージェントから外部 MCP サーバー（Asana）のツールを使う","url":"https://zenn.dev/hrendoh/articles/agentforce-external-mcp-asana","source":"Zenn","published_at":"2026-11-25 10:41","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Agentforceから外部MCPサーバー（Asana）を呼び出す設定手順","summary":"SalesforceのAgentforceエージェントから、外部のMCPサーバー（Asana）を呼び出し、ケースからタスクを起票するまでの設定手順を解説。管理者が認証情報を管理し、エージェントが外部ツールを安全に利用するための接続設定を網羅しています。\n\nSalesforceの外部ログイン情報や権限セットの構成など、実務的な設定フローを具体的に提示。MCPを活用してSalesforceと外部SaaSをシームレスに連携させるための技術的ガイドとなっており、エンタープライズ環境でのAIエージェント活用を目指す開発者にとって非常に有益です。","importance":7},{"title":"Docker のコンテナは何でできているのか。namespace・cgroup・pivot_root・runc を Mac で確かめた","url":"https://zenn.dev/mystery_hat/articles/docker-container-kernel-features-on-mac","source":"Zenn","published_at":"2026-11-25 08:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Dockerコンテナの仕組みをMac環境でnamespace・cgroup等から検証","summary":"Dockerコンテナを構成するLinuxカーネル機能（namespace, cgroup, pivot_root等）を、Mac上のDocker Desktop環境で詳細に検証した実験レポート。\n\nVM内のPID 1とコンテナのプロセスを比較し、user以外の7つの名前空間が分離されていることを確認しました。また、runcがpivot_rootを用いてルートファイルシステムを切り替える仕組みや、overlay2によるレイヤー構造についても解説しており、コンテナの技術的基盤を深く理解するための実践的な内容です。","importance":7},{"title":"AI に文章を書かせるときは、ネストした箇条書きで取捨選択させる - id:onk のはてなブログ","url":"https://onk.hatenablog.jp/entry/2026/11/25/022804","source":"Hatena","published_at":"2026-11-25 10:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIへの指示出しは「ネストした箇条書き」で取捨選択させるのが有効","summary":"コーディングエージェントが生成する文章が冗長で要点が伝わりにくいという課題に対し、ネストした箇条書き形式で出力させ、項目ごとに重要度を判断して取捨選択する手法が紹介されています。\n\nAIに一度箇条書きで構造化させることで、情報の関係性や判断根拠が明確になり、人間がレビュー・修正しやすくなります。Chain of Thoughtの考え方を応用し、エージェントのスキルとして手順を組み込むことで、より質の高いコミットメッセージやPR本文の作成が可能になります。","importance":7},{"title":"[AWS]DMSを試してみる(Database Migraton Service)","url":"https://zenn.dev/77nnaapp/articles/52d5b46af0e72c","source":"Zenn","published_at":"2026-11-25 18:51","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS DMSを用いたMySQLからRDSへの移行手順を解説","summary":"AWS Database Migration Service (DMS) を使用して、EC2上のMySQLからRDS for MySQLへデータを移行する実践的な手順を解説している。VPCの構築からサブネット、セキュリティグループの設定、移行元・移行先エンドポイントの作成、そしてMigration Taskの実行までを網羅している。\n\n特にDMS専用のネットワーク環境構築や、移行元MySQLでの専用ユーザー作成など、実務で必要となる準備ステップが詳細にまとめられている。データベース移行の自動化やクラウド移行を検討しているエンジニアにとって、具体的な構築ガイドとして有用である。","importance":5},{"title":"Claude Code Channels を Windows で自作し、権限確認を外から許可した","url":"https://zenn.dev/ai_hacchu/articles/claude-code-channels-windows-permission-relay","source":"Zenn","published_at":"2026-11-25 09:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude CodeのChannels機能をWindowsで自作し外部から権限確認を許可","summary":"Claude Codeの「Channels」機能を活用し、Windows環境で自作のMCPサーバーを構築して外部（Discord等）からセッションを操作する仕組みが紹介されています。\n\nNode.jsで85行の窓口を作成し、権限確認を外部から応答可能にすることで、ターミナルを開かずにAIエージェントを操作する環境を実現しました。公式ドキュメントにないWindows対応や、auto modeでの権限転送の課題を克服した実践的な開発事例です。","importance":7},{"title":"Apple製モニターを経由して有線LAN接続したらインターネット速度が4分の1に低下したという体験談","url":"https://gigazine.net/news/20261125-monitor-was-cutting-download-speed/","source":"Hatena","published_at":"2026-11-25 08:07","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Apple製モニター経由の有線LAN接続で速度が低下する原因と解決策","summary":"Studio Display XDRをUSB-Cハブとして利用し、Ethernetアダプターを介して有線接続した際に、通信速度が大幅に低下する現象の原因が特定されました。\n\n調査の結果、モニター経由の接続による遅延と、Ethernetアダプターのバースト転送能力（パケット数）の不足により、バッファ溢れとパケット破棄が発生していたことが判明しました。より高性能なチップを搭載したアダプターへの交換により、フルスピードでの通信が可能となりました。","importance":6},{"title":"【自動化】Muse のサイドチャットへ Webhook を届ける MuseKnock の仕組み","url":"https://zenn.dev/codehex/articles/33bc6ee330b880","source":"Zenn","published_at":"2026-11-25 15:12","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MetaのAI「Muse」を外部イベントで動かすツール「MuseKnock」","summary":"MetaのAIエージェント「Muse」を、GitHubやSlackなどの外部イベントと連携させて即座に動かすためのOSSツール「MuseKnock」を開発した。Cloudflare WorkersとDurable Objectを活用し、Webhookを受け取ってMuseのサイドチャットに投稿する仕組みである。\n\n定期実行によるラグを解消し、イベント駆動でAIを呼び出すことで、要約や共有などのタスクを自動化できる。Gadget SDKやMCPサーバーの概念を利用し、Museの機能を拡張する個人開発の好例である。","importance":6},{"title":"モデルの性能が出ないのは AI ゲートウェイのせいかもしれない","url":"https://zenn.dev/google_cloud_jp/articles/7e29a9acf06557","source":"Zenn","published_at":"2026-11-25 07:22","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Code 等から AI ゲートウェイ経由で別プロバイダーのモデルを呼ぶと、HTTP 200 のまま思考のリセットやキャッ…","summary":"Claude Code 等から AI ゲートウェイ経由で別プロバイダーのモデルを呼ぶと、HTTP 200 のまま思考のリセットやキャッシュ失効が起きることがある 異変に気づくには応答品質やエラー率だけでなく、2 ターン目以降の思考トークン数・キャッシュヒット率や、プロバイダー純正のクライアント・API の組み合わせで直接動かしたときとの差を確認するのが有効 ネイティブ API を使える場合はゲートウェイの無変換パススルーを選び、変換を挟む場合はマルチターンの結合テストで状態維持を検証する 1. 期待した性能が出ないときの盲点 新しいモデルを試したり、普段使っている開発ツールの裏側のモデルを切り替えたりしたとき、なぜか期待した性能や応答速度が出ないことがあります。\n\n企業の AI 基盤や評価環境では、認証やコスト管理を一本化するために、通信を中継する AI ゲートウェイ（API プロキシ）を間に挟む構成がとられます。","importance":5}]};
